sp_widget.client_script:
c.checkAvailability = function(hallId, startDate, endDate) {
    if (!startDate || !endDate) {
        // Find the hall and set its message
        angular.forEach(data.halls, function(hall) {
            if (hall.sys_id == hallId) {
                hall.availabilityMessage = 
                'Please select both start and end dates.';
            }
        });
        $scope.$apply();
        return;
    }

    var ga = new GlideAjax('SportsHallAvailabilityAjax');
    ga.addParam('sysparm_name', 'checkAvailability');
    ga.addParam('sysparm_hall_id', hallId);
    ga.addParam('sysparm_start_date', startDate);
    ga.addParam('sysparm_end_date', endDate);

    ga.getXMLAnswer(function(response) {
        // Find the specific hall and update its message
        angular.forEach($scope.data.halls, function(hall) {
            if (hall.sys_id == hallId) {
                hall.availabilityMessage = response == 'available' ?
                'Hall is available!' :
                'Sorry, this hall is already booked for the selected time.';
            }
        });
        $scope.$apply();
    });
};

sp_widget.css:
.sports-hall-list {
  padding: 10px;

  h3 {
    color: #00695C;
    font-weight: bold;
    margin-bottom: 15px;
    padding-bottom: 10px;
    border-bottom: 2px solid #00695C;
  }

  .filter-section input {
    border-radius: 20px;
    border: 1px solid #00695C;
    padding: 8px 15px;

    &:focus {
      outline: none;
      box-shadow: 0 0 5px rgba(0,105,92,0.3);
    }
  }

  .hall-card {
    border: none !important;
    border-radius: 12px !important;
    padding: 18px !important;
    margin-bottom: 15px !important;
    background: white !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08) !important;
    transition: box-shadow 0.2s ease;

    &:hover {
      box-shadow: 0 4px 16px rgba(0,0,0,0.15) !important;
    }

    h4 {
      font-weight: bold;
      font-size: 16px;
    }

    .btn-primary {
      background: #00695C;
      border: none;
      border-radius: 20px;
      padding: 6px 20px;

      &:hover {
        background: #004D40;
      }
    }

    .btn-info {
      border-radius: 20px;
      padding: 4px 15px;
      font-size: 12px;
    }

    .btn-default {
      border-radius: 20px;
      padding: 6px 20px;
    }
  }
}

sp_widget.script:
(function() {
    // Get all available sports halls
    var gr = new GlideRecord('x_1954179_sports_0_sports_hall');
    gr.addActiveQuery();
    gr.orderBy('hall_name');
    gr.query();

    data.halls = [];

    while (gr.next()) {
        var hall = {
            sys_id: gr.getUniqueValue(),
            name: gr.getValue('hall_name'),
            location: gr.getValue('location'),
            capacity: gr.getValue('capacity'),
            facilities: gr.getValue('facilities'),
            available: true // default
        };

        // Check if hall has any active bookings today
        var booking = new GlideRecord('x_1954179_sports_0_sports_hall_booking');
        booking.addQuery('sports_hall', gr.getUniqueValue());
        booking.addQuery('status', 'Approved');

        // Check if current time falls within any booking
        var now = new GlideDateTime();
        booking.addQuery('start_date', '<=', now);
        booking.addQuery('end_date', '>=', now);
        booking.query();

        if (booking.next()) {
            hall.available = false;
        }

        data.halls.push(hall);
    }
})();
